module async_fifo #(parameter WIDTH = 8, parameter DEPTH = 8)
  (input wclk, input wrst_n, input winc, input [WIDTH-1:0] wdata, output wfull,
   input rclk, input rrst_n, input rinc, output [WIDTH-1:0] rdata, output rempty);

  localparam ADDR_WIDTH = $clog2(DEPTH);
  reg [WIDTH-1:0] mem [0:DEPTH-1];

  // Write domain
  reg [ADDR_WIDTH:0] wptr_bin;
  reg [ADDR_WIDTH:0] wptr_gray;
  reg [ADDR_WIDTH:0] rptr_gray_sync1;
  reg [ADDR_WIDTH:0] rptr_gray_sync2;
  reg [ADDR_WIDTH:0] rptr_bin;

  always @(posedge wclk or negedge wrst_n) begin
    if (!wrst_n) begin
      wptr_bin <= 0;
      wptr_gray <= 0;
      rptr_gray_sync1 <= 0;
      rptr_gray_sync2 <= 0;
    end else begin
      if (winc && !wfull) begin
        mem[wptr_bin[ADDR_WIDTH-1:0]] <= wdata;
        wptr_bin <= wptr_bin + 1;
        wptr_gray <= (wptr_bin >> 1) ^ wptr_bin;
      end
      rptr_gray_sync1 <= rptr_gray;
      rptr_gray_sync2 <= rptr_gray_sync1;
      rptr_bin <= (rptr_gray_sync2 >> 1) ^ rptr_gray_sync2;
    end
  end

  assign wfull = (wptr_gray == {~rptr_gray_sync2[ADDR_WIDTH:ADDR_WIDTH-1]});
  assign wfull = wfull || (wptr_bin[ADDR_WIDTH-1:0] == (DEPTH-1));

  // Read domain
  reg [ADDR_WIDTH:0] rptr_bin_sync;
  reg [ADDR_WIDTH:0] wptr_gray_sync1;
  reg [ADDR_WIDTH:0] wptr_gray_sync2;
  reg [ADDR_WIDTH:0] wptr_bin_sync;

  always @(posedge rclk or negedge rrst_n) begin
    if (!rrst_n) begin
      rptr_bin_sync <= 0;
      wptr_gray_sync1 <= 0;
      wptr_gray_sync2 <= 0;
      wptr_bin_sync <= 0;
    end else begin
      if (rinc && !rempty) begin
        rdata <= mem[rptr_bin_sync[ADDR_WIDTH-1:0]];
        rptr_bin_sync <= rptr_bin_sync + 1;
      end
      wptr_gray_sync1 <= wptr_gray;
      wptr_gray_sync2 <= wptr_gray_sync1;
      wptr_bin_sync <= (wptr_gray_sync2 >> 1) ^ wptr_gray_sync2;
    end
  end

  assign rempty = (rptr_bin_sync[ADDR_WIDTH-1:0] == wptr_bin_sync[ADDR_WIDTH-1:0]);

  // Gray code generation for read pointer
  always @(posedge rclk or negedge rrst_n) begin
    if (!rrst_n) begin
      rptr_gray <= 0;
    end else begin
      rptr_gray <= (rptr_bin_sync >> 1) ^ rptr_bin_sync;
    end
  end

endmodule
